use verus::prelude::*;
use vstd::vec::{Vec, vec};

verus! {

    /// Given exactly three strictly positive integers ≤ 1500,
    /// sorts them into non‐decreasing order a ≤ b ≤ c and
    /// returns ['Y','E','S'] if and only if
    ///   • a == 1, or
    ///   • a == 2 && b == 2, or
    ///   • (a,b,c) == (2,4,4), or
    ///   • (a,b,c) == (3,3,3),
    /// otherwise returns ['N','O'].
    fn solve(nums: Vec<i8>) -> Vec<char> {
        // Precondition: exactly 3 elements, each in 1..=1500
        requires(nums.len() == 3);
        requires(forall(|i: usize| i < 3 ==> nums[i] > 0 && nums[i] <= 1500));

        // Postcondition: the result is exactly "YES" or "NO"
        ensures(|res: Vec<char>|
            (res.len() == 3 && res[0] == 'Y' && res[1] == 'E' && res[2] == 'S')
            ||
            (res.len() == 2 && res[0] == 'N' && res[1] == 'O')
        );

        // Extract the three inputs
        let x0 = nums[0];
        let x1 = nums[1];
        let x2 = nums[2];

        // Compute a = min(x0,x1,x2)
        let a = if x0 <= x1 {
            if x0 <= x2 { x0 } else { x2 }
        } else {
            if x1 <= x2 { x1 } else { x2 }
        };

        // Compute c = max(x0,x1,x2)
        let c = if x0 >= x1 {
            if x0 >= x2 { x0 } else { x2 }
        } else {
            if x1 >= x2 { x1 } else { x2 }
        };

        // The middle value b = sum − a − c
        let sum = x0 + x1 + x2;
        let b = sum - a - c;

        // Check the four special patterns
        if a == 1
           || (a == 2 && b == 2)
           || (a == 2 && b == 4 && c == 4)
           || (a == 3 && b == 3 && c == 3)
        {
            vec!['Y', 'E', 'S']
        } else {
            vec!['N', 'O']
        }
    }
}